sys_script_include.script:
var BaseUtils = Class.create();
BaseUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	validateBaseName: function() {
		var base = this.getParameter("sysparm_base");

		var gr = new GlideRecord("x_1519575_traini_1_base_registry");
		gr.addQuery("name", base);
		gr.query();

		if(gr.next()) {
			return "true";
		}
		return "false";
	},

	validateBaseCapacity: function(){
		var baseSysId = this.getParameter("sysparm_base_sys_id");

		var gr = new GlideRecord("x_1519575_traini_1_base_registry");

		if (gr.get(baseSysId)) {
			var baseCapacity = parseInt(gr.max_capacity, 10);

			var members = new GlideAggregate("x_1519575_traini_1_base_member");
			members.addQuery("base", baseSysId);
			members.addQuery("state", "!=", "4");
			members.addAggregate("COUNT");
			members.query();

			if (members.next()) {
				var count = parseInt(members.getAggregate("COUNT"), 10);
				if (count >= baseCapacity) {
					return "true";
				}
			}

			return "false";
		}

	},

	validateCityState: function () {
		var city = this.getParameter("sysparm_city");
		var state = this.getParameter("sysparm_state");

		var grState = new GlideRecord("x_1519575_traini_1_base_registry");
		grState.addQuery("state", state);
		grState.query();

		if(grState.next()) {
			var grCity = new GlideRecord("x_1519575_traini_1_base_registry")
			grCity.addQuery("state", state);
			grCity.addQuery("city", city);
			grCity.query();

			if(grCity.next()) {
				return "true";
			}
			return "false";
		}
	},

	validateBaseManager: function() {
		var manager = this.getParameter("sysparm_manager");

		var gr = new GlideRecord("x_1519575_traini_1_base_registry");
		gr.addQuery("base_manager", manager);
		gr.query();

		if(gr.next()) {
			return "true";
		}
		return "false";
	},

	refQualBase: function() {
		var userId = gs.getUserID();
		var baseNotToBeShown = [];
		var baseToBeShown = [];

		var grMember = new GlideRecord("x_1519575_traini_1_base_member");
		grMember.addQuery("opened_by", userId);
		grMember.addQuery("state", "!=", "4");
		grMember.query();

		if(grMember.next()){
			return "sys_idIN" + baseToBeShown.join(",");
		}

		var grBase = new GlideRecord("x_1519575_traini_1_base_registry");
		grBase.query();

		while(grBase.next()){
			var baseName = grBase.name.toString();
			var baseCapacity = parseInt(grBase.max_capacity, 10);

			var members = new GlideAggregate("x_1519575_traini_1_base_member");
			members.addQuery("base.name", baseName);
			members.addQuery("state", "!=", "4");
			members.addAggregate("COUNT");
			members.query();

			if(members.next() && parseInt(members.getAggregate("COUNT"), 10) >= baseCapacity) {
				baseNotToBeShown.push(grBase.sys_id.toString());
			}

			if(baseNotToBeShown.indexOf(grBase.getUniqueValue()) == -1){
				baseToBeShown.push(grBase.getUniqueValue());
			}
		}


		return "sys_idIN" + baseToBeShown.join(",");


	},

    type: 'BaseUtils'
});
